dark.customCSS:
:root {
	--hds-sidebar: color-mix(in oklab, black 88%, transparent);
	--hds-edge: #ffff00;
	--hds-selected: color-mix(in oklab, #ffff00 22%, transparent);
	--hds-pill: color-mix(in oklab, black 82%, transparent);
	--hds-pill-edge: #ffff00;
	--hds-ring: color-mix(in oklab, white 40%, transparent);
	--hds-drop: #000000;
	--hds-bubble: #ffff00;
	--hds-bubble-text: #000000;
	--hds-heading: #ffff00;
	--hds-mark: #ffff00;
	--hds-mark-text: #000000;
}

/* Windows 3.1 Hot Dog Stand: ketchup, mustard and black, flat Windows
   drop shadows, Open WebUI's own rounded shapes kept. */
#message-input-container {
	background-color: var(--hds-pill) !important;
	border: 2px solid var(--hds-pill-edge);
	box-shadow: 4px 4px 0 var(--hds-drop);
}
#message-input-container:focus-within {
	box-shadow: 0 0 0 3px var(--hds-ring), 4px 4px 0 var(--hds-drop);
}
.chat-user .rounded-3xl {
	background-color: var(--hds-bubble) !important;
	box-shadow: 3px 3px 0 var(--hds-drop);
}
.chat-user .markdown-prose { color: var(--hds-bubble-text); }
#sidebar {
	background-color: var(--hds-sidebar) !important;
	border-inline-end: 3px solid var(--hds-edge);
}
#sidebar-chat-item.selected { background-color: var(--hds-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--hds-heading); font-weight: 800; }
.markdown-prose a { color: var(--hds-heading); text-decoration-thickness: 2px; }
.markdown-prose :is(hr, blockquote) { border-color: var(--hds-edge); }
html { scrollbar-color: var(--hds-edge) transparent; }
::selection { background-color: var(--hds-mark); color: var(--hds-mark-text); }

